declarations.formal_type:
∀ (k : Type u) [inst : Field.{u} k] (E : Type v) [inst_1 : AddCommGroup.{v} E] [inst_2 : Module.{u, v} k E]
  [Module.Finite.{u, v} k E] (A : Subalgebra.{u, v} k (Module.End.{u, v} k E))
  [IsSemisimpleRing.{v} (Subtype.{v + 1} fun x => Membership.mem.{v, v} A x)]
  [FaithfulSMul.{v, v} (Subtype.{v + 1} fun x => Membership.mem.{v, v} A x) E] (T : Type w)
  [inst_6 : AddCommGroup.{w} T]
  [inst_7 :
    Module.{v, w}
      (Subtype.{v + 1} fun x => Membership.mem.{v, v} (Subalgebra.centralizer.{u, v} k (SetLike.coe.{v, v} A)) x) T]
  [IsSimpleModule.{v, w}
      (Subtype.{v + 1} fun x => Membership.mem.{v, v} (Subalgebra.centralizer.{u, v} k (SetLike.coe.{v, v} A)) x) T],
  Exists.{v + 1} fun W =>
    And
      (IsSimpleModule.{v, v}
        (Subtype.{v + 1} fun x => Membership.mem.{v, v} (Subalgebra.centralizer.{u, v} k (SetLike.coe.{v, v} A)) x)
        (Subtype.{v + 1} fun x => Membership.mem.{v, v} W x))
      (Nonempty.{max (v + 1) (w + 1)}
        (LinearEquiv.{v, v, w, v}
          (RingHom.id.{v}
            (Subtype.{v + 1} fun x => Membership.mem.{v, v} (Subalgebra.centralizer.{u, v} k (SetLike.coe.{v, v} A)) x))
          T (Subtype.{v + 1} fun x => Membership.mem.{v, v} W x)))
